  1	// General power-of-2 base conversion, as `bech32.convertbits`.
  2	
  3	/**
  4	 * Regroup `data` from `frombits`-wide symbols into `tobits`-wide ones.
  5	 *
  6	 * Returns `null` (Python's `None`) when a symbol does not fit in `frombits` --
  7	 * which is what makes `convertbits(witprog, 5, 8)` fail for any witness program
  8	 * byte >= 32 -- and, when `pad` is false, when the trailing partial group is
  9	 * either too wide or not all zeroes.
 10	 */
 11	export function convertbits(data, frombits, tobits, pad = true) {
 12	  let acc = 0;
 13	  let bits = 0;
 14	  const ret = [];
 15	  const maxv = (1 << tobits) - 1;
 16	  const maxAcc = (1 << (frombits + tobits - 1)) - 1;
 17	
 18	  for (const value of data) {
 19	    if (value < 0 || value >> frombits) {
 20	      return null;
 21	    }
 22	    acc = ((acc << frombits) | value) & maxAcc;
 23	    bits += frombits;
 24	    while (bits >= tobits) {
 25	      bits -= tobits;
 26	      ret.push((acc >> bits) & maxv);
 27	    }
 28	  }
 29	
 30	  if (pad) {
 31	    if (bits) {
 32	      ret.push((acc << (tobits - bits)) & maxv);
 33	    }
 34	  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) {
 35	    return null;
 36	  }
 37	  return ret;
 38	}
 39	// Segwit address layer -- `bech32.decode` / `bech32.encode`.
 40	//
 41	// This mirrors the BIP-173-only behaviour of the reference module: a witness
 42	// version of 1..16 is accepted with an ordinary bech32 checksum, and bech32m
 43	// (BIP-350) strings are rejected outright.
 44	
 45	import { bech32Decode, bech32Encode } from './codec.mjs';
 46	import { convertbits } from './convert.mjs';
 47	
 48	export const MIN_PROGRAM_LENGTH = 2;
 49	export const MAX_PROGRAM_LENGTH = 40;
 50	export const MAX_WITNESS_VERSION = 16;
 51	
 52	function failure() {
 53	  return [null, null];
 54	}
 55	
 56	/**
 57	 * Decode a segwit address into `[witnessVersion, witnessProgram]`, where the
 58	 * program is a plain array of byte values, or `[null, null]` on any failure.
 59	 *
 60	 * The program-length check deliberately precedes the `data[0]` read: for a
 61	 * checksum-only string the payload is empty, the conversion yields `[]`, and the
 62	 * length test bails out before the witness version would be indexed.
 63	 */
 64	export function decode(hrp, addr) {
 65	  const [hrpGot, data] = bech32Decode(addr);
 66	  if (hrpGot !== hrp) {
 67	    return failure();
 68	  }
 69	
 70	  const decoded = convertbits(data.slice(1), 5, 8, false);
 71	  if (
 72	    decoded === null ||
 73	    decoded.length < MIN_PROGRAM_LENGTH ||
 74	    decoded.length > MAX_PROGRAM_LENGTH
 75	  ) {
 76	    return failure();
 77	  }
 78	  if (data[0] > MAX_WITNESS_VERSION) {
 79	    return failure();
 80	  }
 81	  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
 82	    return failure();
 83	  }
 84	  return [data[0], decoded];
 85	}
 86	
 87	/** Encode a segwit address, or `null` when the result would not round-trip. */
 88	export function encode(hrp, witver, witprog) {
 89	  const addr = bech32Encode(hrp, [witver, ...convertbits(witprog, 8, 5)]);
 90	  const [version, program] = decode(hrp, addr);
 91	  if (version === null && program === null) {
 92	    return null;
 93	  }
 94	  return addr;
 95	}
 96	// Generic bech32 string layer: the character-level validation, the separator
 97	// hunt and the checksum gate. Knows nothing about segwit.
 98	
 99	import {
100	  CHARSET,
101	  CHECKSUM_LENGTH,
102	  MAX_HRP_LENGTH,
103	  charsetIndex,
104	  isCharsetChar,
105	} from './charset.mjs';
106	import { bech32CreateChecksum, bech32VerifyChecksum } from './checksum.mjs';
107	import { isMixedCase, isPrintableAsciiRange } from '../python/text.mjs';
108	
109	/** What a failed decode yields: Python's `(None, None)`. */
110	function failure() {
111	  return [null, null];
112	}
113	
114	/**
115	 * Validate a bech32 string and split it into `[hrp, data]`, or `[null, null]`.
116	 *
117	 * `data` excludes the six checksum symbols. The HRP is returned lower-cased,
118	 * so an all-upper-case address never matches an upper-case HRP argument.
119	 */
120	export function bech32Decode(bech) {
121	  if (!isPrintableAsciiRange(bech) || isMixedCase(bech)) {
122	    return failure();
123	  }
124	
125	  const lowered = bech.toLowerCase();
126	  const pos = lowered.lastIndexOf('1');
127	  // `pos` is both the separator index and the HRP length.
128	  if (pos < 1 || pos + 1 + CHECKSUM_LENGTH > lowered.length || pos > MAX_HRP_LENGTH) {
129	    return failure();
130	  }
131	
132	  const tail = lowered.slice(pos + 1);
133	  for (const char of tail) {
134	    if (!isCharsetChar(char)) {
135	      return failure();
136	    }
137	  }
138	
139	  const hrp = lowered.slice(0, pos);
140	  const data = [];
141	  for (const char of tail) {
142	    data.push(charsetIndex(char));
143	  }
144	  if (!bech32VerifyChecksum(hrp, data)) {
145	    return failure();
146	  }
147	  return [hrp, data.slice(0, -CHECKSUM_LENGTH)];
148	}
149	
150	/** Compute a bech32 string from an HRP and 5-bit data values. */
151	export function bech32Encode(hrp, data) {
152	  const combined = [...data, ...bech32CreateChecksum(hrp, data)];
153	  return `${hrp}1${combined.map((value) => CHARSET[value]).join('')}`;
154	}
155	// Python's `repr()` for the value shapes this program prints: int, None and
156	// list-of-int. `print(x)` uses `str(x)`, which for all of these equals `repr(x)`.
157	
158	export function pyRepr(value) {
159	  if (value === null || value === undefined) {
160	    return 'None';
161	  }
162	  if (Array.isArray(value)) {
163	    return `[${value.map(pyRepr).join(', ')}]`;
164	  }
165	  if (typeof value === 'boolean') {
166	    return value ? 'True' : 'False';
167	  }
168	  if (typeof value === 'string') {
169	    return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
170	  }
171	  return String(value);
172	}
173	// Python's `print` / `sys.stderr.write` mapped onto Node's streams.
174	//
175	// Nothing here calls `process.exit()`. The entry point sets `process.exitCode`
176	// and returns instead, so Node always drains stdout/stderr before terminating --
177	// `process.exit()` truncates pipes because those streams are asynchronous.
178	
179	export function writeStdout(text) {
180	  process.stdout.write(text);
181	}
182	
183	export function writeStderr(text) {
184	  process.stderr.write(text);
185	}
186	
187	/** `print(value)` -- the text followed by a single newline. */
188	export function print(text) {
189	  writeStdout(`${text}\n`);
190	}

  1	// Bech32 alphabet and the constants that bound a well-formed string.
  2	
  3	export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';
  4	
  5	export const GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
  6	
  7	/** Trailing data symbols that carry the BCH checksum. */
  8	export const CHECKSUM_LENGTH = 6;
  9	
 10	/**
 11	 * BIP-173 caps the human-readable part at 83 characters. The reference module
 12	 * enforces that bound and imposes no 90-character limit on the string as a
 13	 * whole: an 83-character HRP with a 40-byte witness program (155 characters
 14	 * total) decodes, while an 84-character HRP is rejected at any total length.
 15	 */
 16	export const MAX_HRP_LENGTH = 83;
 17	
 18	export function charsetIndex(char) {
 19	  return CHARSET.indexOf(char);
 20	}
 21	
 22	export function isCharsetChar(char) {
 23	  return CHARSET.includes(char);
 24	}
 25	// The BCH checksum over GF(32) that bech32 strings carry.
 26	//
 27	// Every intermediate stays inside 30 bits -- `chk` is masked to 25 bits before
 28	// being shifted left by 5, and the generator constants are all below 2**30 --
 29	// so JavaScript's 32-bit bitwise operators are exact here and agree with
 30	// Python's arbitrary-precision integers bit for bit.
 31	
 32	import { CHECKSUM_LENGTH, GENERATOR } from './charset.mjs';
 33	import { codePoints } from '../python/text.mjs';
 34	
 35	export function bech32Polymod(values) {
 36	  let chk = 1;
 37	  for (const value of values) {
 38	    const top = chk >> 25;
 39	    chk = ((chk & 0x1ffffff) << 5) ^ value;
 40	    for (let i = 0; i < GENERATOR.length; i += 1) {
 41	      if ((top >> i) & 1) {
 42	        chk ^= GENERATOR[i];
 43	      }
 44	    }
 45	  }
 46	  return chk;
 47	}
 48	
 49	/** High bits of the HRP, a zero separator, then the low bits. */
 50	export function bech32HrpExpand(hrp) {
 51	  const points = codePoints(hrp);
 52	  return [...points.map((point) => point >> 5), 0, ...points.map((point) => point & 31)];
 53	}
 54	
 55	export function bech32VerifyChecksum(hrp, data) {
 56	  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1;
 57	}
 58	
 59	export function bech32CreateChecksum(hrp, data) {
 60	  const values = [...bech32HrpExpand(hrp), ...data, ...new Array(CHECKSUM_LENGTH).fill(0)];
 61	  const polymod = bech32Polymod(values) ^ 1;
 62	  const checksum = [];
 63	  for (let i = 0; i < CHECKSUM_LENGTH; i += 1) {
 64	    checksum.push((polymod >> (5 * (5 - i))) & 31);
 65	  }
 66	  return checksum;
 67	}
 68	// Facade mirroring the surface of Python's `bech32` module, so callers can
 69	// `import * as bech32` and use `bech32.decode` / `bech32.convertbits` directly.
 70	
 71	export { CHARSET, CHECKSUM_LENGTH, GENERATOR, MAX_HRP_LENGTH } from './charset.mjs';
 72	export {
 73	  bech32CreateChecksum,
 74	  bech32HrpExpand,
 75	  bech32Polymod,
 76	  bech32VerifyChecksum,
 77	} from './checksum.mjs';
 78	export { convertbits } from './convert.mjs';
 79	export { bech32Decode, bech32Encode } from './codec.mjs';
 80	export {
 81	  MAX_PROGRAM_LENGTH,
 82	  MAX_WITNESS_VERSION,
 83	  MIN_PROGRAM_LENGTH,
 84	  decode,
 85	  encode,
 86	} from './segwit.mjs';
 87	// Python `str` primitives that bech32's decoder depends on.
 88	//
 89	// `bech32_decode` inspects its input one code point at a time and compares the
 90	// string against its own `lower()`/`upper()` forms, so these helpers reproduce
 91	// those exact semantics rather than approximating them.
 92	
 93	/**
 94	 * Ordinals of a string, iterated the way Python iterates a `str`:
 95	 * one entry per code point, not per UTF-16 unit.
 96	 */
 97	export function codePoints(text) {
 98	  const points = [];
 99	  for (const char of text) {
100	    points.push(char.codePointAt(0));
101	  }
102	  return points;
103	}
104	
105	/** Python's `not any(ord(x) < 33 or ord(x) > 126 for x in text)`. */
106	export function isPrintableAsciiRange(text) {
107	  for (const char of text) {
108	    const point = char.codePointAt(0);
109	    if (point < 33 || point > 126) {
110	      return false;
111	    }
112	  }
113	  return true;
114	}
115	
116	/**
117	 * Python's `text.lower() != text and text.upper() != text`.
118	 *
119	 * A string with no cased characters at all (e.g. "1231PQYPQA3AQ5Z" has none in
120	 * its digits, but its letters are all upper) is *not* mixed case, which is why
121	 * both halves of the conjunction matter. Callers reject non-ASCII input first,
122	 * so ASCII case mapping is the only behaviour exercised here.
123	 */
124	export function isMixedCase(text) {
125	  return text.toLowerCase() !== text && text.toUpperCase() !== text;
126	}

