import { writeFileSync } from 'node:fs';
import { segwitEncode, bech32Encode, convertbits, CHARSET } from '/tmp/probe/gen.mjs';

const cases = [];
const seen = new Set();
function add(argv) {
  const k = JSON.stringify(argv);
  if (seen.has(k)) return;
  seen.add(k);
  cases.push(argv);
}
function ab(a, b) { add(['--a', a, '--b', b]); }

// ---- helper: emit a v0 address for hrp+prog, plus interesting arg variants
function v0(hrp, prog, { upper = false, mismatch = false } = {}) {
  const addr = segwitEncode(hrp, 0, prog);
  if (addr === null) throw new Error('encode failed ' + hrp);
  ab(hrp, addr);
  if (upper) {
    ab(hrp, addr.toUpperCase());          // all-upper address, lower hrp arg -> OK
    ab(hrp.toUpperCase(), addr.toUpperCase()); // hrpgot lowered -> mismatch
    // mixed case: flip exactly one char in the data part
    const i = addr.length - 1;
    const mixed = addr.slice(0, i) + addr[i].toUpperCase() + addr.slice(i + 1);
    if (mixed !== addr) ab(hrp, mixed);
  }
  if (mismatch) {
    ab(hrp + 'x', addr);
    ab('', addr);
  }
  return addr;
}

const rep = (n, v) => new Array(n).fill(v);
const HRPS_MAIN = ['bc', 'tb', 'ltc', 'test'];
const HRPS_ODD = ['1', 'a1b', 'bc1', '~', '!', '"', '#', '$', '%', '&', "'", '(', ')',
  '*', '+', ',', '.', '/', '0', '123', ':', ';', '<', '=', '>', '?', '@', 'A',
  '[', '\\', ']', '^', '_', '`', 'z', '{', '|', '}', 'q', 'l', 'BC', 'Bc', 'bC'];

// ============ 1. canonical / spec vectors ============
ab('bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4');
ab('bc', 'BC1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4');
ab('BC', 'BC1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4');
ab('bc', 'bc1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4');
ab('tb', 'tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3q0sl5k7');
ab('tb', 'TB1QRP33G0Q5C5TXSP9ARYSRX4K6ZDKFS4NCE4XJ0GDCCCEFVPYSXF3Q0SL5K7');
ab('bc', 'bc1qqypqxpq9qcrsszg2pvxq6rs0zqg3yyc5fcj4z3');
ab('bc', 'bc1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq9e75rs');
ab('bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t5'); // bad checksum
ab('tb', 'tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4'); // hrp mismatch
ab('bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4 '); // trailing space (ord 32)

// ============ 2. all bytes < 32 (LIST result) and >= 32 (None) ============
for (const hrp of HRPS_MAIN) {
  for (const n of [20, 32]) {
    v0(hrp, rep(n, 0), { upper: true, mismatch: true });      // all zero -> LIST
    v0(hrp, rep(n, 0xff), { upper: true, mismatch: true });    // all 0xff -> None
    v0(hrp, rep(n, 31), { upper: true });                      // all 31 -> LIST (boundary)
    v0(hrp, rep(n, 32), { upper: true });                      // all 32 -> None (boundary)
    v0(hrp, rep(n, 30));
    v0(hrp, rep(n, 33));
    v0(hrp, rep(n, 1));
    v0(hrp, rep(n, 128));
    v0(hrp, rep(n, 255));
    v0(hrp, Array.from({ length: n }, (_, i) => i));           // 0..n-1  all < 32 -> LIST
    v0(hrp, Array.from({ length: n }, (_, i) => 31 - (i % 32)));
    v0(hrp, Array.from({ length: n }, (_, i) => (i * 8) % 256));
    v0(hrp, Array.from({ length: n }, (_, i) => (i % 2 ? 31 : 32)));
    v0(hrp, Array.from({ length: n }, (_, i) => (i % 2 ? 32 : 31)));
  }
}

// ============ 3. byte value exactly 31 vs exactly 32 at EVERY position ============
for (const hrp of ['bc', 'tb']) {
  for (const n of [20, 32]) {
    for (let i = 0; i < n; i++) {
      for (const [lo, hi] of [[0, 31], [0, 32], [31, 32], [31, 31], [31, 0], [0, 255], [31, 128]]) {
        const p = rep(n, lo); p[i] = hi; v0(hrp, p);
      }
    }
  }
}
// same 31/32 sweep on a third hrp, cheaper variant set
for (const n of [20, 32]) {
  for (let i = 0; i < n; i++) {
    let p = rep(n, 31); p[i] = 32; v0('ltc', p);
    p = rep(n, 32); p[i] = 31; v0('ltc', p);
  }
}

// ============ 4. odd HRPs with v0 programs ============
for (const hrp of HRPS_ODD) {
  v0(hrp, rep(20, 0));
  v0(hrp, rep(20, 31));
  v0(hrp, rep(20, 32));
  v0(hrp, rep(32, 31));
  v0(hrp, rep(32, 255));
  const a = segwitEncode(hrp, 0, rep(20, 7));
  ab(hrp, a);
  ab(hrp, a.toUpperCase());
  ab(hrp.toUpperCase(), a.toUpperCase());
}
// hrps whose value argparse must accept/reject
ab('-', segwitEncode('-', 0, rep(20, 3)));
ab('-0', segwitEncode('-0', 0, rep(20, 3)));
ab('-5', segwitEncode('-5', 0, rep(20, 3)));
ab(' bc', segwitEncode(' bc', 0, rep(20, 3)));
ab('b c', segwitEncode('b c', 0, rep(20, 3)));

// ============ 5. HRP LENGTH SWEEP with a real v0 program (no 90-char limit!) ============
for (const n of [20, 32]) {
  for (let L = 1; L <= 86; L++) {
    const hrp = 'q'.repeat(L);
    const addr = segwitEncode(hrp, 0, rep(n, n === 20 ? 5 : 6));
    ab(hrp, addr);
    if (L >= 47 && L <= 53) ab(hrp, addr.toUpperCase()); // straddles total==90
    if (L >= 28 && L <= 34) ab(hrp, addr.toUpperCase());
    if (L >= 82) ab(hrp, addr.toUpperCase());
  }
}
// mixed hrp alphabet at the 83/84 boundary
for (const L of [1, 2, 82, 83, 84, 85]) {
  const hrp = ('abcdefghij0123456789~!@#$%^&*()' .repeat(9)).slice(0, L);
  for (const n of [20, 32]) ab(hrp, segwitEncode(hrp, 0, rep(n, 17)));
}

// ============ 6. raw-data length sweep for witver 0 ============
for (const hrp of ['bc', 'tb']) {
  for (let L = 0; L <= 70; L++) {
    ab(hrp, bech32Encode(hrp, [0, ...rep(L, 0)]));
    ab(hrp, bech32Encode(hrp, [0, ...rep(L, 31)]));
  }
}
